//! v1.15 X-P1-1: dated SEC Section 31 + FINRA TAF schedule against
//! `tests/golden/expected_regulatory_fees.json` (generated by
//! `python/tools/make_golden_regulatory_fees.py`), the shipped schedule
//! file, and the simulated venue wiring (sell-side only, off by default).

use marketdata::{EventType, MarketEvent};
use serde_json::Value;
use venue::{OrderRequest, OrderType, RegulatoryFeeSchedule, SimVenueConfig, SimulatedVenue};

fn repo_path(rel: &str) -> std::path::PathBuf {
    std::path::PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../..").join(rel)
}

fn golden() -> Value {
    let text = std::fs::read_to_string(repo_path("tests/golden/expected_regulatory_fees.json"))
        .expect("expected_regulatory_fees.json");
    serde_json::from_str(&text).expect("golden JSON")
}

#[test]
fn golden_cases() {
    let g = golden();
    let sched = RegulatoryFeeSchedule::from_json(&g["schedule"]).expect("schedule");
    let tol = g["tolerance"].as_f64().unwrap();
    let cases = g["cases"].as_array().unwrap();
    assert!(cases.len() >= 10);
    for c in cases {
        let qty = c["qty"].as_i64().unwrap() as f64;
        let notional = qty
            * c["qty_unit"].as_f64().unwrap()
            * c["price_ticks"].as_i64().unwrap() as f64
            * c["tick_size"].as_f64().unwrap();
        let side = c["side"].as_u64().unwrap() as u8;
        let ts = c["ts"].as_i64().unwrap();
        let got = sched.fee(side, qty, notional, ts);
        let label = c["label"].as_str().unwrap();
        if c.get("error").is_some() {
            assert!(got.is_err(), "{label}: expected an error");
        } else {
            let want = c["fee"].as_f64().unwrap();
            let got = got.expect(label);
            assert!((got - want).abs() <= tol, "{label}: {got} != {want}");
        }
    }
}

#[test]
fn shipped_schedule_matches_golden_copy() {
    let shipped =
        RegulatoryFeeSchedule::load(&repo_path("configs/reference/regulatory_fee_schedule.json"))
            .expect("shipped schedule");
    let copy = RegulatoryFeeSchedule::from_json(&golden()["schedule"]).unwrap();
    assert_eq!(shipped, copy);
}

// 2026-06-12 14:30 UTC: Section 31 $20.60/M, TAF $0.000195 capped $9.79.
const T0: i64 = 1_781_222_400_000_000_000 + 52_200_000_000_000;

fn add(seq: u64, side: u8, price: i64, qty: i64) -> MarketEvent {
    MarketEvent {
        event_id: seq,
        instrument_id: 1,
        venue_id: 1,
        exchange_ts: T0 + seq as i64,
        receive_ts: T0 + seq as i64,
        sequence: seq,
        event_type: EventType::Add.as_u8(),
        side,
        price_ticks: price,
        qty,
        order_id: seq,
        trade_id: 0,
    }
}

fn taker_fee(with_fees: bool, side: u8) -> f64 {
    let cfg = SimVenueConfig {
        venue_id: 1,
        latency_ns: 150_000,
        taker_fee_per_share: 0.003,
        maker_rebate_per_share: 0.002,
    };
    let mut v = SimulatedVenue::new(cfg).unwrap();
    if with_fees {
        let sched =
            RegulatoryFeeSchedule::load(&repo_path("configs/reference/regulatory_fee_schedule.json"))
                .unwrap();
        v = v.with_regulatory_fees(sched, 0.01).unwrap();
    }
    v.on_market_event(&add(1, 0, 10_000, 500)).unwrap();
    v.on_market_event(&add(2, 1, 10_001, 500)).unwrap();
    let order = OrderRequest {
        order_id: 77,
        instrument_id: 1,
        side,
        qty: 100,
        price_ticks: 0,
        order_type: OrderType::Market.as_u8(),
        venue_id: 1,
        strategy_id: "S1".to_string(),
        urgency: 1.0,
        timestamp: T0 + 1_000,
    };
    let reports = v.submit(&order).unwrap();
    reports.iter().filter(|r| r.filled_qty > 0).map(|r| r.fees).sum()
}

#[test]
fn simulated_venue_charges_sells_only_when_enabled() {
    let notional = 100.0 * 10_000.0 * 0.01;
    let want = 20.60 * notional / 1e6 + (0.000195_f64 * 100.0).min(9.79);
    let diff = taker_fee(true, 1) - taker_fee(false, 1);
    assert!((diff - want).abs() <= 1e-12, "{diff} != {want}");
    assert_eq!(taker_fee(true, 0), taker_fee(false, 0));
}
